def solver_modules():
    from ..kernel import inputs, pipeline
    return inputs, pipeline


def ensure_kernel():
    _inputs, pipeline = solver_modules()
    tree = bpy.data.node_groups.get(pipeline.NAME)
    if tree is None:
        tree = pipeline.build()
    return tree


@contextlib.contextmanager
def suspend():
    """Make a multi-part source/metadata transaction invisible to the handler."""
    global _busy
    _busy += 1
    try:
        yield
    finally:
        _busy -= 1


def _member_pair(member):
    if hasattr(member, 'section_id'):
        return member.section_id, member.section_end
    return member[:2]


def junction_inputs(net):
    """Translate stable IDs to disposable local indices; preserve authored paths."""
    old, _ = solver_modules()
    sections = {s.id: s for s in net.canonical.sections}
    ownership = net.canonical.section_streets()
    used = {}
    result = []
    for intersection in net.intersection_records.values():
        connectors = [c for c in net.connector_records.values()
                      if c.intersection_id == intersection.id]
        if len(connectors) < 3:
            raise ValueError(f'Intersection {intersection.id}: the current kernel needs at least three connectors')

        def angle(c):
            sid, end = _member_pair(c.members[0])
            points = sections[sid].vertices
            endpoint, nextpoint = (points[0], points[1]) if end == 0 else (points[-1], points[-2])
            return math.atan2(nextpoint[1]-endpoint[1], nextpoint[0]-endpoint[0]) % math.tau

        connectors.sort(key=angle)
        streets, conn_inputs, profiles = [], [], []
        for connector_index, connector in enumerate(connectors):
            if getattr(connector,'radius_override',-1.) > 0:
                next_id = connectors[(connector_index+1)%len(connectors)].id
                if getattr(connector,'radius_next_connector_id',-1) != next_id:
                    raise ValueError(f'Connector {connector.id}: corner adjacency changed; reassign its radius override to an explicit adjacent pair')
            members = []
            ordered_members = sorted(zip(connector.lateral_orders, connector.members))
            for order, raw in ordered_members:
                sid, end = _member_pair(raw)
                used.setdefault(sid, []).append((intersection.id, end))
                section = sections[sid]
                local = len(streets)
                # A local kernel member is one explicit authored Section. The
                # persistent owning Street/order remain in the controller.
                streets.append(old.StreetInput(ownership[sid], (old.SectionInput(
                    sid, section.vertices, section.width, section.offset),)))
                head,tail=-1,-1
                if connector.bundle_id>=0:
                    bundle=net.bundle_records[connector.bundle_id]
                    entry=next(m for m in bundle.members if m[0]==ownership[sid])
                    head,tail=entry[2:4]
                members.append(old.MemberInput(local, end == 0, order,
                               connector.bundle_id, head, tail))
            first_id, _ = _member_pair(connector.members[0])
            default = net.section_records[first_id]
            override = getattr(connector, 'use_profile_override', False)
            rise = connector.rise if override else default.rise
            preset = connector.preset if override else default.preset
            profile = old.ProfileInput(rise, old.FLAT if preset == 'FLAT' else old.SMOOTH_CROWN,
                                       getattr(connector, 'separator', False))
            radius = getattr(connector, 'radius_override', -1.)
            if radius <= 0:
                radius = intersection.radius
            profiles.append(profile)
            conn_inputs.append(old.ConnectorInput(connector.id, tuple(members), len(profiles)-1,
                radius=radius, item_kind=old.BUNDLE_ITEM if connector.bundle_id >= 0 else old.STREET_ITEM,
                bundle_source_id=connector.bundle_id))
        junction = old.PreparedJunction(intersection.id, intersection.position,
                    tuple(streets), tuple(conn_inputs), tuple(profiles),
                    intersection.datum, net.cell_size)
        old.validate_initial_scope(junction)
        result.append(junction)
    if set(used) != set(sections):
        missing = sorted(set(sections)-set(used))
        raise ValueError(f'No generation owner for Sections {missing}; unattached spans require the later carriageway builder')
    duplicated = [sid for sid, owners in used.items() if len(owners) != 1]
    if duplicated:
        raise ValueError(f'Sections {duplicated} enter more than one kernel; create an explicit Section boundary between junction neighborhoods')
    _validate_partition(net, result)
    return tuple(result)


def _validate_partition(net, junctions):
    """Qualify explicit midspan seams; do not silently bridge incompatible data."""
    sections = {s.id: s for s in net.canonical.sections}
    counts = {}
    effective_profiles = {}
    for junction in junctions:
        half_widths = []
        for connector in junction.connectors:
            profile = junction.profiles[connector.profile_index]
            bounds = []
            for member in connector.members:
                section = junction.streets[member.street_index].sections[0]
                points = section.centerline if member.leaving else section.centerline[::-1]
                tangent = Vector(points[1])-Vector(points[0]); tangent.z = 0; tangent.normalize()
                right = Vector((tangent.y,-tangent.x,0.))
                lateral = (Vector(points[0])-Vector(junction.location)).dot(right)
                lateral += section.offset if member.leaving else -section.offset
                bounds.append((lateral-section.width/2,lateral+section.width/2))
                effective_profiles[section.source_id] = (profile.preset, profile.rise,
                                                        profile.separator)
            half_widths.append((max(b[1] for b in bounds)-min(b[0] for b in bounds))/2)
        nv = max(4,4*math.ceil(max(half_widths)/(4*net.cell_size)))
        for street in junction.streets:
            counts[street.sections[0].source_id] = (nv, junction.datum)
    for street in net.canonical.streets:
        for (aid, af), (bid, bf) in zip(street.sections, street.sections[1:]):
            a,b = sections[aid],sections[bid]
            ap=a.vertices if af else a.vertices[::-1]
            bp=b.vertices if bf else b.vertices[::-1]
            at=(Vector(ap[-1])-Vector(ap[-2])).normalized()
            bt=(Vector(bp[1])-Vector(bp[0])).normalized()
            ar,br=effective_profiles[aid],effective_profiles[bid]
            if at.dot(bt)<1.-1e-6:
                raise ValueError(f'Street {street.id}: bent Section-to-Section join needs the later bend builder')
            if (abs(a.width-b.width)>1e-6 or
                abs(a.offset*(1 if af else -1)-b.offset*(1 if bf else -1))>1e-6 or
                ar[0]!=br[0] or abs(ar[1]-br[1])>1e-7 or ar[2] or br[2]):
                raise ValueError(f'Street {street.id}: width/offset/profile transition is not supported at the explicit seam')
            if counts[aid][0] != counts[bid][0] or abs(counts[aid][1]-counts[bid][1])>1e-6:
                raise ValueError(f'Street {street.id}: seam sampling or datum mismatch; both junctions must use compatible cross-sections')
    return counts


def _cache_collection(controller):
    name = 'Prochitecture Streets / Derived inputs / '+controller.st_network.network_uuid[:8]
    collection = bpy.data.collections.get(name)
    if collection is None:
        collection = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(collection)
    collection.hide_render = True
    return collection


def _carrier(controller, junction, collection):
    name = f'Prochitecture Streets / Cache {controller.st_network.network_uuid[:8]} / intersection {junction.source_id}'
    obj = bpy.data.objects.get(name)
    old, _pipeline = solver_modules()
    mesh = old.carrier_mesh(junction, name+' data')
    if obj is None:
        obj = bpy.data.objects.new(name, mesh)
        collection.objects.link(obj)
    else:
        previous=obj.data;obj.data=mesh
        if previous.users == 0:bpy.data.meshes.remove(previous)
    obj.matrix_world = Matrix.Identity(4)
    obj.st_generated_controller = controller
    obj.hide_render=True;obj.hide_select=True;obj.hide_set(True)
    obj['stage5_transport']='Disposable data only; authored source geometry is elsewhere'
    obj['intersection_id']=junction.source_id
    obj['has_grass']=any(profile.separator for profile in junction.profiles)
    return obj


def _synchronize_carriers(controller, collection, carriers):
    """Collection is the GN input, so remove obsolete derived children explicitly."""
    keep = set(carriers)
    for obj in tuple(collection.objects):
        if obj in keep:
            continue
        if obj.st_generated_controller != controller:
            raise ValueError('Derived junction collection contains an unexpected object')
        mesh = obj.data
        bpy.data.objects.remove(obj, do_unlink=True)
        if mesh.users == 0:
            bpy.data.meshes.remove(mesh)
    if collection.children:
        raise ValueError('Derived junction collection must not contain nested collections')
    for obj in carriers:
        if obj.name not in collection.objects:
            collection.objects.link(obj)


def _assembly():
    """One top-level modifier tree for every network; bindings are modifier inputs."""
    existing = bpy.data.node_groups.get(network_nodes.NAME)
    if existing is not None:
        return existing
    return network_nodes.build(ensure_kernel())


def _set_modifier(obj,key,value):
    _old,pipeline=solver_modules()
    pipeline.set_input(obj,key,value)


def _set_status(controller,state,message):
    props=controller.st_network
    if props.status!=state:props.status=state
    if props.diagnostic!=message:props.diagnostic=message


def refresh(controller, *, force=False, raise_errors=False, _legacy=False):
    """Synchronous native refresh; handlers use the same path as operators/tests."""
    global _busy
    _pending.pop(controller.name, None)
    if (controller.get('st_network_v8',False) or controller.get('st_network_v7',False) or controller.get('st_network_v6',False) or controller.get('st_network_v5',False)) and not _legacy:
        from . import unified_runtime
        try:
            return unified_runtime.refresh(controller,force=force,raise_errors=raise_errors)
        finally:
            _watch_recovery(controller)
    if controller.get('st_network_v4',False) and not _legacy:
        from . import path_runtime
        try:
            return path_runtime.refresh(controller,force=force,raise_errors=raise_errors)
        finally:
            _watch_recovery(controller)
    if _busy:
        return False
    _index_legacy_sources()
    started=time.perf_counter()
    try:
        with suspend():
            # Flush authored transform changes before reading matrix_world.
            # Newly created/moved objects can otherwise expose stale matrices
            # while registry positions already contain the new world values.
            bpy.context.view_layer.update()
            net=model.read_network(controller)
            # Canonical identity deliberately ignores object grouping and mesh
            # numbering. Native GN bindings must still refresh after regrouping
            # or a managed operation that replaces/reorders the source meshes.
            signature=(net.signature, tuple(
                (sid, source.object.as_pointer(), source.object.data.as_pointer(),
                 source.vertex_indices, source.edge_indices)
                for sid, source in sorted(net.section_sources.items())))
            key=controller.as_pointer()
            if not force and _last.get(key)==signature:
                return False
            junctions=junction_inputs(net)
            live_collection, live_sections, live_seams, vertex_count, edge_count = live_bindings.compile_sources(controller, net)
            sampling = _validate_partition(net, junctions)
            collection=_cache_collection(controller)
            carriers=tuple(_carrier(controller,j,collection) for j in junctions)
            for carrier, junction in zip(carriers, junctions):
                nv = sampling[junction.streets[0].sections[0].source_id][0]
                live_bindings.bind_carrier(carrier.data,junction,live_sections,live_seams,nv)
            _synchronize_carriers(controller,collection,carriers)
            tree=_assembly()
            modifier=next((m for m in controller.modifiers if m.type=='NODES'),None)
            if modifier is None:modifier=controller.modifiers.new('Editable Street network','NODES')
            previous_group=modifier.node_group
            modifier.node_group=tree
            _set_modifier(controller,'Junction Inputs',collection)
            _set_modifier(controller,'Source Objects',live_collection)
            _set_modifier(controller,'Source Vertex Count',vertex_count)
            _set_modifier(controller,'Source Edge Count',edge_count)
            _set_modifier(controller,'Metres to Blender Units',1/net.scale_length)
            _set_modifier(controller,'Mesh Resolution',controller.st_network.resolution)
            _set_modifier(controller,'Height Exaggeration',controller.st_network.exaggeration)
            _set_modifier(controller,'Enabled',True)
            for name in ('Pavement','Grass'):
                mat=bpy.data.materials.get('Prochitecture Streets / '+name)
                if mat:_set_modifier(controller,name,mat)
            if (previous_group and previous_group!=tree and previous_group.users==0
                    and previous_group.name.startswith('Prochitecture Streets / Editable network / ')):
                bpy.data.node_groups.remove(previous_group)
            controller.update_tag()
            _last[key]=signature
            _metrics[controller.name]={'normalization_seconds':time.perf_counter()-started,
                                       'junctions':len(junctions),'sections':len(net.canonical.sections)}
            bpy.context.view_layer.update()
            evaluated=controller.evaluated_get(bpy.context.evaluated_depsgraph_get())
            evaluated_mesh=evaluated.to_mesh()
            try:
                if not len(evaluated_mesh.polygons):
                    raise ValueError('GN rejected the network geometry: check corner fit, available approach length and quad validity')
            finally:
                evaluated.to_mesh_clear()
            _metrics[controller.name]['refresh_and_evaluation_seconds']=time.perf_counter()-started
            _set_status(controller,'READY',f'{len(junctions)} intersections; {len(net.canonical.sections)} Sections; live input and GN geometry valid')
            return True
    except Exception as exc:
        with suspend():
            _last.pop(controller.as_pointer(),None)
            mod=next((m for m in controller.modifiers if m.type=='NODES'),None)
            if mod and mod.node_group and any(s.name=='Enabled' for s in mod.node_group.interface.items_tree):
                _set_modifier(controller,'Enabled',False)
            _set_status(controller,'INVALID',str(exc))
        if raise_errors:raise
        return False


def refresh_all(*, force=False, raise_errors=False):
    changed=0
    for obj in tuple(bpy.data.objects):
        if hasattr(obj,'st_network') and obj.st_network.enabled:
            changed+=bool(refresh(obj,force=force,raise_errors=raise_errors))
    return changed


@persistent
def _changed(scene, depsgraph):
    # Native networks already read coordinates and edge parameters in GN.
    # Only the old implementation needs an observer for native source edits.
    if _busy:
        return
    for update in depsgraph.updates:
        original = update.id.original
        # A failed metadata compile can disable stale bindings. Retry that
        # network when its authored source is repaired; ignore generated
        # outputs so an invalid result cannot schedule itself indefinitely.
        owner = getattr(original, 'st_source_controller', None)
        if owner is not None and _needs_binding_recovery(owner):
            request_refresh(owner)
        names = set(_legacy_watch.get(original.as_pointer(), ()))
        names.update(_recovery_watch.get(original.as_pointer(), ()))
        for name in names:
            controller = bpy.data.objects.get(name)
            if controller is not None:
                request_refresh(controller)


def request_refresh(controller):
    """Coalesce explicit metadata edits; never rebuild from a viewport redraw."""
    if _timer_active and not _busy and controller.st_network.enabled:
        _pending[controller.name] = True
        _metadata_history.add(controller.name)


def native_edits(controller):
    return any(controller.get('st_network_v'+str(version), False) for version in (4, 5, 6, 7, 8))


def _needs_binding_recovery(controller):
    """A native geometric rejection can recover without Python recompilation.

    Only a failed metadata compile disables the modifier. Keep recovery watching
    for that case, including failures before any modifier could be constructed.
    """
    if controller.st_network.status != 'INVALID':
        return False
    if not native_edits(controller):
        return True
    modifier = next((m for m in controller.modifiers if m.type == 'NODES'), None)
    if modifier is None or modifier.node_group is None:
        return True
    socket = next((s for s in modifier.node_group.interface.items_tree
        if s.item_type == 'SOCKET' and s.in_out == 'INPUT' and s.name == 'Enabled'), None)
    if socket is None:
        return True
    enabled = (getattr(modifier.properties.inputs, socket.identifier).value
        if hasattr(modifier, 'properties') else modifier.get(socket.identifier, False))
    return not enabled


def _watch_recovery(controller):
    """Watch failed bindings, not live GN diagnostics, including BMesh updates."""
    for key, names in tuple(_recovery_watch.items()):
        names.discard(controller.name)
        if not names:
            del _recovery_watch[key]
    if not _needs_binding_recovery(controller):
        return
    try:
        sources = model._sources(controller)
    except ValueError:
        sources = ()
    for source in sources:
        for data in (source, source.data):
            _recovery_watch.setdefault(data.as_pointer(), set()).add(controller.name)


def _index_legacy_sources():
    _legacy_watch.clear()
    for controller in bpy.data.objects:
        if not getattr(getattr(controller, 'st_network', None), 'enabled', False):
            continue
        if native_edits(controller):
            _watch_recovery(controller)
            continue
        try:
            sources = model._sources(controller)
        except ValueError:
            sources = ()
        collection = controller.st_network.source_collection
        if collection is not None:
            for item in (collection, *collection.children_recursive):
                _legacy_watch.setdefault(item.as_pointer(), set()).add(controller.name)
        for obj in (controller, *sources):
            for datablock in (obj, obj.data):
                if datablock is not None:
                    _legacy_watch.setdefault(datablock.as_pointer(), set()).add(controller.name)


def _tick():
    if not _timer_active:
        return None
    from . import editing
    if _pending and not _busy and not editing.is_editing():
        pending = tuple(_pending)
        _pending.clear()
        for name in pending:
            controller = bpy.data.objects.get(name)
            if controller is not None and controller.st_network.enabled:
                refresh(controller)
    return .15


@persistent
def _loaded(_):
    _last.clear()
    _pending.clear()
    _metadata_history.clear()
    _recovery_watch.clear()
    _index_legacy_sources()


@persistent
def _history_restored(_):
    # Undo/redo restores the derived bindings too. Metadata may have been
    # undone before its deferred refresh ran, so reconcile once after history
    # changes. No periodic scan follows this explicit event.
    _pending.clear()
    _recovery_watch.clear()
    _index_legacy_sources()
    for name in tuple(_metadata_history):
        controller = bpy.data.objects.get(name)
        if controller is not None and controller.st_network.enabled:
            request_refresh(controller)


def _initialize_sources():
    """Addon registration can run while Blender exposes restricted bpy.data."""
    if not _timer_active:
        return None
    if not hasattr(bpy.data, 'objects'):
        return .05
    _index_legacy_sources()
    return None


def register():
    global _timer_active
    if _changed not in bpy.app.handlers.depsgraph_update_post:
        bpy.app.handlers.depsgraph_update_post.append(_changed)
    if _loaded not in bpy.app.handlers.load_post:
        bpy.app.handlers.load_post.append(_loaded)
    for handlers in (bpy.app.handlers.undo_post, bpy.app.handlers.redo_post):
        if _history_restored not in handlers:handlers.append(_history_restored)
    _timer_active=True
    if hasattr(bpy.data, 'objects'):
        _index_legacy_sources()
    elif not bpy.app.timers.is_registered(_initialize_sources):
        bpy.app.timers.register(_initialize_sources, first_interval=0.)
    if not bpy.app.timers.is_registered(_tick):bpy.app.timers.register(_tick,first_interval=.15,persistent=True)


def unregister():
    global _timer_active
    _timer_active=False
    if bpy.app.timers.is_registered(_initialize_sources):
        bpy.app.timers.unregister(_initialize_sources)
    for handlers,fn in ((bpy.app.handlers.depsgraph_update_post,_changed),
                         (bpy.app.handlers.load_post,_loaded),
                         (bpy.app.handlers.undo_post,_history_restored),
                         (bpy.app.handlers.redo_post,_history_restored)):
        if fn in handlers:handlers.remove(fn)
    if bpy.app.timers.is_registered(_tick):bpy.app.timers.unregister(_tick)
    _last.clear()
    _pending.clear()
    _legacy_watch.clear()
    _recovery_watch.clear()
    _metadata_history.clear()
